"4-Achs-Sätze mit X/Y/Z und A zusammen: Viele Steuerungen rechnen dort Grad wie Millimeter, der Fräser läuft dann am Werkstück zu langsam oder zu schnell. „Umgerechnet“ schreibt den F-Wert so, dass eine solche Steuerung den gewünschten Vorschub an der Schneide fährt. „Zeitreziprok“ schaltet auf G93 und gibt in jedem Satz 1/Zeit an – eindeutig, wenn die Steuerung G93 kennt.":"Blok 4 paksi dengan X/Y/Z dan A bersama: banyak kawalan mengira darjah seperti milimeter di situ, lalu pemotong bergerak terlalu perlahan atau terlalu laju pada bahan kerja. “Ditukar” menulis nilai F supaya kawalan sedemikian menjalankan kadar suapan yang dikehendaki pada mata pemotong. “Masa songsang” beralih kepada G93 dan menyatakan 1/masa dalam setiap blok – jelas, jika kawalan mengenali G93.",
