"Abstand Anfang / Ende":"Jarak permulaan / penghujung",
"Abstand Anfang / Ende macht aus der Lasche eine Teillasche. Weitere geschlossene Profile in der Skizze werden zu Ausschnitten in der Platte. Bohrungen und Fenster in einer Lasche: Mitte entlang der Kante (bei einer gebogenen Kante entlang des Bogens), Mitte ab Ende der Biegung, Größe – sie erscheinen auch in der Abwicklung. Geht eine gebogene Kante ohne Knick in ihre Nachbarkante über und haben beide eine Lasche mit gleichem Biegewinkel, laufen die Laschen ohne Freischnitt ineinander über. „Kontur aus Skizze“ schneidet die geschlossenen Profile einer Skizze aus der Lasche: ihr X läuft entlang der Kante, ihr Y in die Lasche hinein, der Nullpunkt liegt am Kantenanfang auf dem Ende der Biegung (verschiebbar).":"Jarak permulaan / penghujung menjadikan bebibir sebagai bebibir separa. Profil tertutup lain dalam lakaran menjadi potongan keluar pada plat. Lubang dan tetingkap dalam bebibir: pusat sepanjang tepi (pada tepi melengkung sepanjang lengkok), pusat dari penghujung lenturan, saiz – ia turut muncul dalam bentangan. Jika tepi melengkung beralih ke tepi jirannya tanpa sengkang dan kedua-duanya mempunyai bebibir dengan sudut lenturan yang sama, bebibir bersambung antara satu sama lain tanpa potongan pelepasan. „Kontur daripada lakaran“ memotong profil tertutup sesebuah lakaran daripada bebibir: X-nya berjalan sepanjang tepi, Y-nya ke dalam bebibir, titik sifar terletak pada permulaan tepi di penghujung lenturan (boleh dialihkan).",
