"Alle Flächen des Merkmals wählen: bei einer Bohrung die Wand (und Senkung, Boden), bei einer Tasche Wände und Boden, bei einem Zapfen Mantel und Stirnfläche. Das Merkmal wandert um X/Y/Z; die alte Stelle wird geschlossen. Geht auch bei importierten STEP-Teilen ohne Verlauf. Beim ersten Mal lädt der große Geometriekern (einige Sekunden).":"Pilih semua muka ciri: untuk lubang dinding (dan benam, dasar), untuk poket dinding dan lantai, untuk bos sisi dan muka hujung. Ciri bergerak sebanyak X/Y/Z; lokasi lama ditutup. Juga berfungsi pada bahagian STEP diimport tanpa sejarah. Kali pertama, kernel geometri besar dimuatkan (beberapa saat).",
"Alle Flächen wählen, die verschwinden sollen (bei einer Tasche Wände und Boden, bei einer Bohrung die Wand, bei einer Verrundung die Rundung). Die Nachbarflächen werden über die Lücke verlängert. Der Schritt rechnet bei Änderungen am Körper mit; beim ersten Mal lädt dafür der große Geometriekern (einige Sekunden).":"Pilih semua muka yang hendak dihilangkan (untuk poket dinding dan dasar, untuk lubang dindingnya, untuk fillet muka bulat). Muka jiran dipanjangkan merentasi jurang. Langkah dikira semula apabila jasad berubah; kali pertama kernel geometri penuh dimuatkan untuk ini (beberapa saat).",
