"Dieser Browser kann keinen Ordner als Speicherort verwenden – in der WerkFab-App, in Chrome oder in Edge geht es.":"Pelayar ini tidak dapat menggunakan folder sebagai lokasi simpanan – ia berfungsi dalam aplikasi WerkFab, Chrome atau Edge.",
"Dieser Browser unterstützt keine SpaceMouse (WebHID). Bitte Chrome, Edge oder die Desktop-App verwenden.":"Pelayar ini tidak menyokong SpaceMouse (WebHID). Sila gunakan Chrome, Edge atau aplikasi desktop.",
