"Drehen: Das Teil muss rotationssymmetrisch um die Z-Achse liegen. Z0 = Planfläche oben, X = Durchmesser.":"Pelarikan: bahagian mesti simetri putaran pada paksi Z. Z0 = muka hadapan di atas, X = diameter.",
"Drehen: Drehpunkt anklicken, dann den Winkel mit der Maus zeigen (Vorschau). Esc beendet.":"Putar: klik titik pusat putaran, kemudian tunjukkan sudut dengan tetikus (pratonton). Esc untuk tamat.",
"Drehen: Durchmesser, auf dem der Revolver schaltet (Okuma, LinuxCNC). 0 = Rohteil-Ø + 200 mm":"Pelarikan: diameter tempat turet bergerak (Okuma, LinuxCNC). 0 = Ø bahan mentah + 200 mm",
"Drehen: Elemente wählen, dann Drehpunkt anklicken und den Winkel mit der Maus zeigen (Vorschau); auch als Kopie":"Putar: pilih elemen, kemudian klik titik putaran dan tunjukkan sudut dengan tetikus (pratonton); juga sebagai salinan",
