"Drehmaschine mit Y-Achse: Schlüsselflächen, Konturen und Taschen auf der Planfläche fahren mit feststehendem Teil (C fest) in X und Y – genauer als die Polar-Interpolation. Was über den Y-Weg hinausgeht, bleibt bei der Polar-Interpolation.":"Mesin larik dengan paksi Y: permukaan kunci, kontur dan poket pada muka hujung dijalankan dengan bahagian tegar (C tetap) dalam X dan Y – lebih tepat daripada interpolasi kutub. Apa yang melebihi perjalanan Y kekal dengan interpolasi kutub.",
