"Durchzug {0}: Vorbohrung Ø {1} mm wird auf Ø {2} mm aufgeweitet (Faktor {3}).":"Kolar tarikan {0}: lubang awal Ø {1} mm diperbesar kepada Ø {2} mm (faktor {3}).",
"Durchzug {0}: liegt {1} mm neben dem Rand (weniger als 2 × Blechdicke) – der Rand beult aus.":"Kolar tarikan {0}: terletak {1} mm dari tepi (kurang daripada 2 × ketebalan kepingan) – tepi menggelembung.",
"Durchzug {0}: zu hoch für diese Bohrung (die Vorbohrung bliebe ohne Durchmesser)":"Kolar tarikan {0}: terlalu tinggi untuk lubang ini (lubang awal tidak akan tinggal sebarang diameter)",
"Durchzug: der Rand einer runden Bohrung wird zu einem Kragen hochgezogen, etwa als Gewindedurchzug. Der Bohrungsdurchmesser der Skizze ist der fertige Innendurchmesser; im Zuschnitt wird die kleinere Vorbohrung geschnitten.":"Kolar tarikan: tepi lubang bulat ditarik ke atas menjadi kolar, contohnya sebagai kolar tarikan untuk ulir. Diameter lubang dalam lakaran ialah diameter dalam siap; dalam blank potongan, lubang awal yang lebih kecil dipotong.",
