"Ein Fusion-Design mit seiner Zeitachse übernehmen: über das Export-Skript für Fusion":"Ambil reka bentuk Fusion beserta garis masanya: melalui skrip eksport untuk Fusion",
"Ein Gelenk anlegen: ZUSAMMENBAU → „Gelenk“ (J), erst das bewegliche Teil, dann das feste anklicken, Art „Drehgelenk“ oder „Schiebegelenk“.":"Cipta sendi: PEMASANGAN → “Sendi” (J), klik bahagian bergerak dahulu, kemudian yang tetap, jenis “Sendi putaran” atau “Sendi gelongsor”.",
"Ein Rechteck zeichnen: Werkzeug „Rechteck“ (R), zwei Ecken anklicken. Maße kann man direkt eintippen, z. B. 80 und 50.":"Lukis segi empat tepat: alat “Segi empat tepat” (R), klik dua bucu. Dimensi boleh ditaip terus, cth. 80 dan 50.",
"Ein Rechtsklick in einen Dialog (nicht in ein Eingabefeld) drückt dessen OK-Schaltfläche":"Klik kanan dalam dialog (bukan dalam medan input) menekan butang OK-nya",
"Ein anderes gespeichertes Design als Komponente einfügen":"Sisip reka bentuk lain yang disimpan sebagai komponen",
"Ein eingefügter Satz verschiebt alle folgenden Satznummern – so zählen sie nicht als Änderung":"Blok yang disisipkan mengalihkan semua nombor blok berikutnya – dengan ini ia tidak dikira sebagai perubahan",
"Ein fertiges Teil mit Konstruktion und Fräsbearbeitung":"Bahagian siap dengan reka bentuk dan pengisaran",
"Ein gerollter Rand über 350° schließt sich zum Rohr – das ist so nicht herstellbar":"Tepi tergulung melebihi 350° tertutup menjadi paip – ia tidak boleh dibuat begini",
"Ein geschlossenes Netz in einen Volumenkörper umwandeln (jedes Dreieck wird eine Fläche)":"Tukar jejaring tertutup kepada jasad pepejal (setiap segi tiga menjadi satu muka)",
"Ein leeres Design beginnen":"Mulakan reka bentuk kosong",
"Ein runder Fräser lässt in jeder Innenecke seinen Radius stehen – ein eckiges Gegenstück passt dann nicht hinein. Der Freistich fährt an jeder scharfen Innenecke kurz in die Ecke und zurück.{0}{1}":"Pengisar bulat meninggalkan jejarinya pada setiap sudut dalam – pasangan bersudut tidak akan muat. Pelepasan bergerak sebentar ke dalam sudut dan kembali pada setiap sudut dalam yang tajam.{0}{1}",
"Ein verbundener Agent arbeitet am geöffneten Entwurf: Er liest und ändert die Zeitachse, fragt Körper, Volumen und Fehler ab, holt Normteile aus dem Bauteilkatalog, lässt sich ein Bild der Ansicht geben, exportiert STEP oder STL, legt Werkzeuge und Fertigungsoperationen an und gibt das NC-Programm aus – das vor dem ersten Schnitt zu prüfen bleibt. Auf Dateien, Einstellungen und andere Entwürfe hat er keinen Zugriff. Jede Änderung ist ein Schritt, den Strg+Z zurücknimmt.":"Ejen yang disambungkan bekerja pada reka bentuk yang dibuka: ia membaca dan mengubah garis masa, menanyakan jasad, isi padu dan ralat, mengambil bahagian piawai daripada katalog bahagian, mendapatkan gambar paparan, mengeksport STEP atau STL, mencipta alat dan operasi pembuatan serta mengeluarkan program NC – yang masih perlu disemak sebelum pemotongan pertama. Ia tiada akses kepada fail, tetapan dan reka bentuk lain. Setiap perubahan ialah satu langkah yang dibatalkan oleh Ctrl+Z.",
"Ein zweiter Klick auf die Schaltfläche des Zeichenwerkzeugs schaltet zurück auf Auswählen":"Klik kedua pada butang alat lukisan beralih kembali ke Pilih",
