"Eine .f3d-Datei ist ein geschlossenes Format – die Zeitachse darin kann kein anderes Programm lesen. Fusion selbst gibt sie aber über seine Skript-Schnittstelle heraus:":"Fail .f3d ialah format tertutup – garis masa di dalamnya tidak dapat dibaca oleh program lain. Namun Fusion sendiri mengeluarkannya melalui antara muka skripnya:",
