"Eine Bahn entlang jeder Innenecke/Hohlkehle, in der das Werkzeug zwei Flächen zugleich berührt – zum Ausräumen nach dem Schlichten.":"Satu laluan di sepanjang setiap sudut dalam/fillet tempat alat menyentuh dua muka serentak – untuk pembersihan selepas penamat.",
