"Fläche anklicken – die Bohrung entsteht mit":"Klik muka – lubang dibuat bersama",
"Fläche anklicken: an jedem Klickpunkt entsteht die Durchgangsbohrung für die Schraube (ISO 273, Reihe mittel) durch alle Teile, die dort aufeinanderliegen – für Senkschrauben mit 90°-Senkung, für Zylinderschrauben auf Wunsch mit Senkbohrung (DIN 974-1, Reihe 1) so tief wie der Kopf. Die Schraube sitzt gleich darin. Bohrung und Schraube lassen sich danach im Verlauf ändern.":"Klik muka: pada setiap titik klik dibuat lubang lalu untuk skru (ISO 273, siri sederhana) menerusi semua bahagian yang bertindih di situ – untuk skru benam dengan benam 90°, untuk skru kepala silinder secara pilihan dengan benam silinder (DIN 974-1, siri 1) sedalam kepala. Skru terus terletak di dalamnya. Lubang dan skru boleh diubah kemudian pada garis masa.",
"Fläche eines Körpers anklicken: ihr Rand kommt als Kontur in die Skizze. Eine Kante anklicken projiziert nur diese Kante (Kreise bleiben Kreise). Projizierte Geometrie ist violett.":"Klik muka jasad: sempadannya ditambah ke lakaran sebagai kontur. Klik tepi memproyeksikan tepi itu sahaja (bulatan kekal bulatan). Geometri terproyeksi berwarna ungu.",
