"Gemeinsame Schnittkanten nur einmal schneiden":"Potong tepi potongan bersama sekali sahaja",
"Gemeinsame Schnittkanten: liegen zwei Zuschnitte genau eine Schnittfuge auseinander (beim Schachteln als Abstand die Schnittfuge eintragen), fällt ihre Bahn auf der gemeinsamen Kante zusammen und wird nur einmal geschnitten. Der Anschnitt liegt nie in einem Nachbarteil: ist neben einer Kontur kein freier Abfall, wird auf der Kontur eingestochen. Nach „Vorschau“ zeigt ein Bild je Tafel die Bahn, bevor die Dateien gespeichert werden.":"Tepi potongan bersama: jika dua keping potongan terletak tepat sejarak satu kerf (masukkan kerf sebagai jarak semasa penyusunan), laluan keduanya bertindih pada tepi bersama dan dipotong sekali sahaja. Lead-in tidak pernah terletak dalam bahagian bersebelahan: jika tiada sisa bebas di sebelah kontur, penebukan dibuat pada kontur. Selepas „Pratonton”, satu gambar bagi setiap helaian menunjukkan laluan sebelum fail disimpan.",
