"Gerade Linien der Skizze, die zu keinem Profil gehören (auch Hilfslinien). Biegung: die Linie ist die Mitte der Biegezone, die Skizze dort der Zuschnitt – das größte Stück der Platte bleibt liegen, alles jenseits der Linie schwenkt mit seinen Laschen mit. Die Linie gilt über die ganze Platte. Sicke: eine Rippe entlang der Linie, im Querschnitt und an den Enden rund; das Blech behält seine Dicke.":"Garis lurus lakaran yang tidak tergolong dalam sebarang profil (termasuk garis bantu). Lenturan: garis ialah tengah zon lenturan dan lakaran di situ ialah blank potongan – bahagian plat yang terbesar kekal di tempatnya, segala-galanya di seberang garis berayun bersama bebibirnya. Garis itu terpakai pada seluruh plat. Rusuk tekan: rusuk di sepanjang garis, bulat pada keratan rentas dan di hujungnya; kepingan mengekalkan ketebalannya.",
"Gerade Nuten (Langloch oder Linie mit Nutbreite) gehen als Nutzyklus der Steuerung heraus.":"Alur lurus (alur atau garisan dengan lebar alur) dikeluarkan sebagai kitar alur pengawal.",
