"Geschafft! Das Teil steht in der Zeitleiste unten – ein Doppelklick auf einen Schritt ändert ihn nachträglich. Weiter geht es mit „Maße als Parameter“ oder „Vom Teil zum NC-Programm“.":"Selesai! Bahagian itu berada dalam garis masa di bawah – dwiklik langkah untuk menyuntingnya kemudian. Teruskan dengan “Dimensi sebagai parameter” atau “Dari bahagian ke program NC”.",
"Geschlossen":"Tertutup",
"Geschlossen (Gehrung)":"Tertutup (mitar)",
"Geschlossen: Laschen an zwei Nachbarkanten laufen bis zur Winkelhalbierenden der Ecke und lassen dort den Spalt frei. Die Eckfreistellung sitzt, wo sich die Biegezonen kreuzen – in der Abwicklung und im gebogenen Teil. Auch eine Lasche an einer gebogenen Kante wird an einer echten Ecke auf Gehrung geschnitten (dort ohne Eckfreistellung).":"Tertutup: bebibir pada dua tepi bersebelahan berjalan hingga pembahagi dua sudut dan membiarkan jurang di situ. Kelegaan sudut terletak di tempat zon lenturan bersilang – dalam bentangan rata dan pada bahagian yang dilentur. Bebibir pada tepi melengkung juga dipotong secara mitar pada sudut sebenar (di situ tanpa kelegaan sudut).",
"Geschlossene Kette {0}":"Rantai tertutup {0}",
"Geschlossene Profile begrenzen den Bereich.":"Profil tertutup mengehadkan kawasan.",
"Geschlossene Profile der aktiven Skizze farbig füllen":"Isi profil tertutup dalam lakaran aktif dengan warna",
"Geschlossene Profile werden zu ebenen Flächen – z. B. Deckel und Boden, um Flächen anschließend zu einem Körper zusammenzufügen.":"Profil tertutup menjadi permukaan satah – cth. penutup atas dan bawah, untuk menjahit permukaan menjadi jasad kemudian.",
