"Gespeichert werden Blechdicke {0} mm, Biegeradius innen {1} mm und K-Faktor {2}. Die Regel steht danach bei jedem Blech in der Liste „Blechregel“ – auch in anderen Projekten auf diesem Rechner.":"Yang disimpan: ketebalan kepingan {0} mm, jejari lenturan dalam {1} mm dan faktor K {2}. Selepas itu peraturan ini ada dalam senarai „Peraturan kepingan“ bagi setiap kepingan – juga dalam projek lain pada komputer ini.",
