"Gewindebohrung im untersten Teil":"Lubang berulir pada bahagian paling bawah",
"Gewindebohrung im untersten Teil: die Durchgangsbohrung endet, wo das unterste Teil beginnt; dort entsteht das Kernloch mit Gewinde – drei Gewindegänge tiefer, als die Schraube reicht, oder durch das ganze Teil. Liegt nur ein Teil unter dem Punkt, bekommt es das Gewinde von der Fläche an. „Länge passend zur Einschraubtiefe“ nimmt die nächste Länge der Reihe, mit der die Schraube etwa so tief im Gewinde sitzt, wie ihr Gewinde dick ist (Richtwert für Stahl) – aber nie länger, als das Teil dick ist.":"Lubang bertap pada bahagian paling bawah: lubang tembus berakhir di tempat bahagian paling bawah bermula; di situ terhasil lubang teras dengan ulir – tiga lilitan ulir lebih dalam daripada hujung skru, atau menembusi seluruh bahagian. Jika hanya satu bahagian berada di bawah titik itu, ia mendapat ulir bermula dari muka. „Panjang sesuai kedalaman pemasangan skru“ mengambil panjang seterusnya dalam siri yang menjadikan skru terletak dalam ulir sedalam lebih kurang ketebalan ulirnya (nilai panduan untuk keluli) – tetapi tidak pernah lebih panjang daripada ketebalan bahagian itu.",
"Gewindebohrung {0} – Einschraubtiefe nur {1} mm":"lubang berulir {0} – kedalaman skru masuk hanya {1} mm",
"Gewindebohrung {0}, Einschraubtiefe {1} mm":"lubang berulir {0}, kedalaman skru masuk {1} mm",
"Gewindebohrung: gebohrt wird das Kernloch; das Gewinde erscheint als Gewindedarstellung am Modell und mit seinem Namen in der Zeichnung.":"Lubang berulir: lubang teras digerudi; ulir muncul sebagai paparan ulir pada model dan dengan namanya dalam lukisan.",
