"Gleiche Durchmesser ergeben ein Rohr, verschiedene einen Kegelstumpf. Die Abwicklung wird auf der neutralen Faser gerechnet (Innenfläche + K-Faktor × Blechdicke); beim Runden liegt sie näher an der Blechmitte als beim Abkanten – üblich ist ein K-Faktor von 0,45 bis 0,5. Mit einer Blechregel gelten deren Dicke und K-Faktor. Der Nahtspalt bleibt am größeren Durchmesser offen (0 = stumpf gestoßen, im Körper dann ein Schlitz von 0,01 mm).":"Diameter yang sama menghasilkan paip, yang berbeza menghasilkan kon terpenggal. Bentangan dikira pada gentian neutral (permukaan dalam + faktor K × ketebalan kepingan); semasa penggelekan ia lebih dekat dengan tengah kepingan berbanding pelenturan tekan – faktor K lazim ialah 0,45 hingga 0,5. Dengan peraturan kepingan, ketebalan dan faktor K peraturan itu digunakan. Celah kelim kekal terbuka pada diameter yang lebih besar (0 = cantuman tumpu, dalam jasad kemudian celah 0,01 mm).",
"Gleiche Länge oder gleichen Radius erzwingen":"Paksa panjang sama atau jejari sama",
