"Gleichmäßige Dreiecke dieser Größe: lange Kanten werden geteilt, danach wird auf die Dreieckszahl eines gleichmäßigen Netzes reduziert. Gut vor dem Glätten oder Formen von Scans.":"Segi tiga seragam pada saiz ini: tepi panjang dibahagi, kemudian dikurangkan kepada bilangan segi tiga mesh seragam. Sesuai sebelum melicinkan atau membentuk imbasan.",
