"Halbzeug: Nennmaße der Norm, auf jede Länge zugeschnitten. Nicht jede Paarung von Maß und Wanddicke ist bei jedem Händler am Lager. Ein Rohr entlang einer Skizzenlinie – auch um Ecken und Bögen – legt der Befehl „Rohr“ an.":"Bahan separuh siap: dimensi nominal piawaian, dipotong kepada sebarang panjang. Tidak setiap gandingan saiz dan ketebalan dinding ada dalam stok di setiap pembekal. Paip sepanjang garis lakaran – juga di sekeliling sudut dan lengkok – dibuat oleh arahan „Paip“.",
