"Heidenhain: an der Steuerung die Datenübertragung über Ethernet freigeben (wie für TNCremo, LSV2, Port 19000); Standardordner TNC 640 TNC:\\nc_prog\\, iTNC 530 TNC:\\. FTP: Port 21, Ordner z. B. /_N_WKS_DIR oder /NC. Netzwerkordner: Pfad wie \\\\MASCHINE\\NC oder Z:\\NC. DNC: Wandler als TCP-Server (raw), meist Port 4001; an der Steuerung „Abarbeiten extern“, DNC oder TAPE starten.":"Heidenhain: benarkan pemindahan data melalui Ethernet pada kawalan (seperti untuk TNCremo, LSV2, port 19000); folder lalai TNC 640 TNC:\\nc_prog\\, iTNC 530 TNC:\\. FTP: port 21, folder cth. /_N_WKS_DIR atau /NC. Folder rangkaian: laluan seperti \\\\MASCHINE\\NC atau Z:\\NC. DNC: penukar sebagai pelayan TCP (raw), biasanya port 4001; pada kawalan mulakan „Jalankan luaran“, DNC atau TAPE.",
