"Im Setup gewählt, bestimmt die Maschine Postprozessor, Eilgang (Laufzeit) und die Grenzwert-Prüfungen.":"Apabila dipilih dalam setup, mesin menentukan pasca-pemproses, gerak pantas (masa larian) dan semakan had.",
