"Importierte Körper sind ohne Konstruktionshistorie, lassen sich aber weiterbearbeiten (Verrundung, Fase, Ausschneiden …) und für CAM verwenden. Mit „Y-Achse oben“ werden Modelle aus Programmen mit Y nach oben richtig hingestellt.":"Jasad yang diimport tiada sejarah reka bentuk, tetapi boleh diedit lagi (fillet, chamfer, potong …) dan digunakan untuk CAM. Dengan „Paksi Y ke atas“ model daripada program dengan Y ke atas diletakkan dengan betul.",
