"Installierte Windows-App und Linux-AppImage laden das Update selbst; sonst öffnet sich die Download-Seite":"Aplikasi Windows yang dipasang dan AppImage Linux memuat turun kemas kini sendiri; jika tidak, halaman muat turun dibuka",
