"JSON kopieren":"Salin JSON",
"Je Operation zwei Q-Parameter am Programmanfang: der erste verschiebt die Tiefe (DL, + = weniger tief), der zweite das seitliche Aufmaß (DR, + = mehr Aufmaß; wirkt nur bei Radiuskorrektur an der Steuerung RL/RR). An der Maschine eine Zahl ändern statt Sätze suchen.":"Dua parameter Q bagi setiap operasi di awal program: yang pertama mengalihkan kedalaman (DL, + = kurang dalam), yang kedua elaun bahan sisi (DR, + = lebih elaun; hanya berkesan dengan pampasan jejari dalam kawalan RL/RR). Ubah satu nombor pada mesin dan bukannya mencari blok.",
"Je Skizze die erste Kurve – offen oder geschlossen. Die Kurven werden mit einer Haut verbunden (Fläche ohne Dicke).":"Lengkung pertama setiap lakaran – terbuka atau tertutup. Lengkung disambung dengan kulit (permukaan tanpa ketebalan).",
"Je Tafel eine Datei. Die Bahn läuft um die halbe Schnittfuge (beim Fräsen den halben Fräser) neben dem Umriss im Abfall; Ausschnitte kommen vor dem Umriss ihres Teils, jede Kontur beginnt mit einem Anschnitt aus dem Abfall. Kiemenschlitze werden auf ihrer Linie geschnitten. Haltestege: so viele Stellen je Umriss bleiben stehen (Laser, Plasma, Wasserstrahl: der Strahl setzt dort aus; Fräsen: der Fräser hebt auf halbe Blechdicke), Umrisse unter 40 mm Länge bekommen keine. „Steuerung“ legt fest, womit der Strahl ein- und ausgeschaltet wird; die Einstechzeit steht als G4 im Programm, außer die Steuerung sticht selbst ein. Nullpunkt ist die linke untere Ecke der Tafel, beim Fräsen Z0 die Blechoberseite. Das Programm vor dem Einsatz an der Maschine oder in einem NC-Simulator prüfen.":"Satu fail bagi setiap helaian. Laluan berjalan di sebelah kontur, dalam sisa, sejauh separuh kerf (semasa pengisaran, separuh pemotong); potongan keluar didahulukan sebelum kontur bahagiannya, dan setiap kontur bermula dengan lead-in dari sisa. Celah louver dipotong pada garisnya. Tab penahan: sebanyak itu tempat bagi setiap kontur dibiarkan (laser, plasma, jet air: pancaran berhenti di situ; pengisaran: pemotong naik ke separuh ketebalan kepingan); kontur yang lebih pendek daripada 40 mm tidak mendapatnya. “Pengawal” menentukan cara pancaran dihidupkan dan dimatikan; masa tebukan ditulis sebagai G4 dalam atur cara melainkan pengawal menebuk sendiri. Titik sifar ialah sudut kiri bawah helaian; semasa pengisaran Z0 ialah bahagian atas kepingan. Semak atur cara pada mesin atau dalam simulator NC sebelum digunakan.",
"Je Werkzeug alle Teile (weniger Werkzeugwechsel)":"Semua bahagian bagi setiap alat (kurang tukar alat)",
"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"Setiap paksi secara berasingan: klik tepi, bucu, muka atau lubang. Paksi yang tidak ditetapkan diambil daripada titik bahan mentah.",
"Jede Bohrung wird mit ihren Koordinaten einzeln angefahren (X/Y je Bohrung) – kein Lochkreis- oder Rastermuster.":"Setiap lubang didekati satu per satu dengan koordinatnya (X/Y bagi setiap lubang) – tiada corak bulatan lubang atau grid.",
"Jede Operation als Unterprogramm (LBL) am Programmende, Aufruf mit CALL LBL":"Setiap operasi sebagai subatur cara (LBL) di penghujung atur cara, dipanggil dengan CALL LBL",
"Jede Variante berechnen und als STEP, STL oder 3MF speichern (eine ZIP-Datei)":"Kira setiap varian dan simpan sebagai STEP, STL atau 3MF (satu fail ZIP)",
"Jeder Kreis der Skizze ist ein Bohrungsmittelpunkt. Gebohrt wird entgegen der Skizzennormalen (ins Material).":"Setiap bulatan lakaran ialah pusat lubang. Gerudi dibuat berlawanan dengan normal lakaran (ke dalam bahan).",
"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"Setiap bulatan lakaran diulang dengan diputar mengelilingi pusat (dalam koordinat lakaran) – bulatan pada jarak jejari bulatan pic menghasilkan bulatan lubang.",
"Jeder Kreis der Skizze wird zum Raster: Abstände in X und Y der Skizze (auch negativ).":"Setiap bulatan lakaran menjadi grid: jarak dalam X dan Y lakaran (juga negatif).",
"Jeder Schritt ist gegen Volumen, Körperzahl und Schwerpunkt aus Fusion geprüft. Skizzen kommen mit festen Maßen, ohne Abhängigkeiten.":"Setiap langkah disemak terhadap isi padu, bilangan jasad dan pusat graviti daripada Fusion. Lakaran datang dengan dimensi tetap, tanpa kekangan.",
"Jeder sichtbare Körper wird ein Glied mit Netz (STL, in Metern), Masse und Trägheit, jedes Gelenk ein Gelenk mit Achse und Grenzen. Die jetzige Stellung ist die Nullstellung. Mit einem Paketnamen stehen die Netze im URDF als package://Name/meshes/…, sonst als relativer Pfad.":"Setiap jasad yang kelihatan menjadi pautan dengan jejaring (STL, dalam meter), jisim dan inersia, setiap sendi menjadi sendi dengan paksi dan had. Pose semasa ialah pose sifar. Dengan nama pakej, jejaring dinyatakan dalam URDF sebagai package://Name/meshes/…, jika tidak sebagai laluan relatif.",
"Jedes # im Skizzentext wird durch die Nummer ersetzt, mit Nullen aufgefüllt (SN-#### → SN-{0}). Bei mehreren Teilen in einer Aufspannung bekommt jedes Teil die nächste Nummer: {1}{2}.":"Setiap # dalam teks lakaran diganti dengan nombor, diisi dengan sifar (SN-#### → SN-{0}). Dengan beberapa bahagian dalam satu setup, setiap bahagian mendapat nombor seterusnya: {1}{2}.",
"Jedes Design liegt als .ofab-Datei im Ordner und wird nach jeder Änderung neu geschrieben. Dateien, die dort hineinkopiert werden, erscheinen hier.":"Setiap reka bentuk disimpan sebagai fail .ofab dalam folder dan ditulis semula selepas setiap perubahan. Fail yang disalin ke dalamnya akan muncul di sini.",
"Jedes Teil hat seinen eigenen Nullpunkt in der Steuerung (G54, G55 … bzw. Bezugspunkt-Nummer in der Tabelle – Heidenhain Zyklus 247). Alle Nullpunkte vorher an der Maschine setzen.":"Setiap bahagian mempunyai titik sifar sendiri dalam kawalan (G54, G55 … atau nombor pratetap dalam jadual – kitaran Heidenhain 247). Tetapkan semua titik sifar pada mesin terlebih dahulu.",
"Jedes eigene Maß und jeder Toleranzrahmen bekommt eine Nummer in einem Kreis. Die Liste enthält Nennmaß, Toleranz, Höchst- und Mindestmaß und Felder für den Istwert. Maße ohne eigene Toleranz bekommen die Allgemeintoleranz.":"Setiap dimensi sendiri dan setiap bingkai toleransi mendapat nombor dalam bulatan. Senarai mengandungi saiz nominal, toleransi, saiz maksimum dan minimum serta medan untuk nilai sebenar. Dimensi tanpa toleransi sendiri mendapat toleransi am.",
"Jetzigen Stand festhalten":"Simpan keadaan semasa",
"Jetzt einen Punkt auf dem zweiten Schenkel.":"Sekarang pilih satu titik pada kaki kedua.",
"Jetzt festhalten":"Simpan sekarang",
"Jetzt jede Richtung einmal bis zum Anschlag: schieben, ziehen, drücken, kippen, drehen (10 s) …":"Sekarang gerakkan setiap arah sekali hingga had: gelongsor, tarik, tolak, condong, pulas (10 s) …",
