"Kalibrieren: zwei Punkte im Bild anklicken, deren Abstand bekannt ist, und den wirklichen Abstand eingeben – das Bild bekommt den richtigen Maßstab.":"Tentukur: klik dua titik pada imej yang jaraknya diketahui dan masukkan jarak sebenar – imej mendapat skala yang betul.",
