"Kante {0} ist zu kurz für eine Lasche":"Tepi {0} terlalu pendek untuk bebibir",
"Kante {0}: Biegewinkel über 180° ist nicht herstellbar.":"Tepi {0}: sudut lenturan melebihi 180° tidak boleh dihasilkan.",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestaucht (Faltengefahr); der Zuschnitt ist dort eine Näherung.":"Tepi {0}: bebibir pada tepi melengkung – pinggirnya dimampatkan sebanyak {1} % semasa pembentukan (risiko berkedut); bentangan di situ hanyalah anggaran.",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestreckt (Rissgefahr); der Zuschnitt ist dort eine Näherung.":"Tepi {0}: bebibir pada tepi melengkung – pinggirnya diregangkan sebanyak {1} % semasa pembentukan (risiko retak); bentangan di situ hanyalah anggaran.",
"Kante {0}: das Laschenmaß {1} mm ist kleiner als die Biegung ({2} mm)":"Tepi {0}: dimensi bebibir {1} mm lebih kecil daripada lenturan ({2} mm)",
"Kante {0}: der Bogen ist zu eng für diese Lasche":"Tepi {0}: lengkok terlalu sempit untuk bebibir ini",
"Kante {0}: die Abstände lassen keine Lasche übrig.":"Tepi {0}: jarak tidak meninggalkan bebibir.",
"Kante {0}: die Lasche kreuzt eine Biegelinie – mit „Abstand Anfang / Ende“ vor der Biegung enden lassen":"Tepi {0}: bebibir bersilang dengan garis lenturan – biarkan ia berakhir sebelum lenturan dengan „Jarak permulaan / penghujung“",
"Kante {0}: die Lasche liegt in einer Biegezone":"Tepi {0}: bebibir terletak dalam zon lenturan",
"Kante {0}: ein Ausschnitt gehört zu einer Lasche, die es nicht gibt.":"Tepi {0}: sebuah potongan keluar milik bebibir yang tidak wujud.",
"Kante {0}: ein Ausschnitt in der Lasche liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Tepi {0}: sebuah potongan keluar pada bebibir terletak {1} mm di sebelah lenturan (kurang daripada 2 × ketebalan kepingan) – ia terherot semasa dilenturkan.",
"Kante {0}: ein Ausschnitt liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Tepi {0}: sebuah potongan keluar terletak {1} mm di sebelah lenturan (kurang daripada 2 × ketebalan kepingan) – ia akan herot semasa melentur.",
"Kante {0}: ein Ausschnitt ragt über die Lasche hinaus.":"Tepi {0}: sebuah potongan keluar menjulur melepasi bebibir.",
"Kante {0}{1}: Lasche {2} mm ist kürzer als 2 × Blechdicke – auf der Abkantpresse kaum zu biegen.":"Tepi {0}{1}: bebibir {2} mm lebih pendek daripada 2 × ketebalan kepingan – hampir tidak dapat dilentur pada mesin tekan lentur.",
"Kante {0}{1}: Saum {2} mm ist kürzer als 4 × Blechdicke – er lässt sich schlecht zudrücken.":"Tepi {0}{1}: lipatan tepi {2} mm lebih pendek daripada 4 × ketebalan kepingan – sukar ditekan rapat.",
"Kante {0}{1}: geschlossener Saum (Innenradius {2} mm) – wird in zwei Hüben gebogen und zugedrückt; harte Werkstoffe reißen dabei an der Außenseite.":"Tepi {0}{1}: lipatan tepi tertutup (jejari dalam {2} mm) – dilentur dalam dua hentaman dan ditekan rapat; bahan keras retak pada bahagian luar apabila berbuat demikian.",
