"Kappe loslassen und „Nullpunkt kalibrieren“ wählen. Danach jede Richtung ausprobieren: der Balken soll sich bewegen, in Ruhe in der grauen Totzone bleiben.":"Lepaskan penutup dan pilih “Tentukur titik sifar”. Kemudian cuba setiap arah: bar harus bergerak dan kekal dalam zon mati kelabu semasa rehat.",
"Kappe schieben = verschieben, drücken/ziehen = zoomen, kippen und drehen = Modell drehen. In Skizzen nur Verschieben und Zoomen. SpaceMouse Pro/Enterprise: T, F, R = Ansicht oben, vorne, rechts. Falls nichts passiert: 3Dconnexion-Treiber kurz beenden und neu verbinden.":"Gelongsor penutup = alih, tolak/tarik = zum, condong dan pulas = putar model. Dalam lakaran hanya alih dan zum. SpaceMouse Pro/Enterprise: T, F, R = paparan atas, depan, kanan. Jika tiada apa-apa berlaku: tutup pemacu 3Dconnexion seketika dan sambung semula.",
