"Kugel-, Schaft-, Torus- oder Konusfräser. Ein Kugelfräser behält seine Bahn; andere Fräser werden geneigt und entlang ihrer Achse verschoben, bis sie am Teil anliegen, ohne es zu verletzen. Höchstens die größte Neigung; wo Schaft oder Halter das Teil berühren würden, richtet sich das Werkzeug auf. Ausgabe als Werkzeugvektor (Heidenhain, Sinumerik, Fanuc), sonst als 3-Achs-Bahn.":"Pengisar hujung bebola, rata, torus atau tirus. Pengisar bebola mengekalkan laluannya; pengisar lain dicondongkan dan dialihkan sepanjang paksinya sehingga menyentuh bahagian tanpa merosakkannya. Paling banyak kecondongan terbesar; di mana batang atau pemegang akan menyentuh bahagian, alat menegak semula. Output sebagai vektor alat (Heidenhain, Sinumerik, Fanuc), jika tidak sebagai laluan 3-paksi.",
