"Lasche an Lasche: Winkel + biegt in dieselbe Richtung weiter (U-Profil, Falz mit 180°), − in die Gegenrichtung (Z-Stufe, Hutprofil). Saum: der Rand der Lasche wird um 180° auf sich selbst zurückgelegt – offen mit einem Spalt von einer Blechdicke, geschlossen flach zugedrückt; mit − 180° liegt er auf der anderen Seite. Das Feld R ist der Innenradius nur dieser Biegung (leer = wie beim Blech). Für einen Saum direkt an der Plattenkante die Lasche selbst auf 180° stellen. Kröpfung: zwei Biegungen gegeneinander (− 45° und + 45°) – der Rand läuft parallel versetzt weiter; Versatz über die Länge des schrägen Stücks und die Winkel.":"Bebibir pada bebibir: sudut + melentur terus ke arah yang sama (profil U, lipatan 180°), − ke arah bertentangan (anjakan Z, profil topi). Lipatan tepi: tepi bebibir dilipat 180° ke atas dirinya sendiri – terbuka dengan celah setebal satu kepingan, tertutup ditekan rata; dengan − 180° ia terletak di sebelah lagi. Medan R ialah jejari dalam bagi lenturan ini sahaja (kosong = seperti pada kepingan). Untuk lipatan tepi terus pada tepi plat, tetapkan bebibir itu sendiri kepada 180°. Anjakan: dua lenturan bertentangan (− 45° dan + 45°) – tepi diteruskan selari dan teranjak; jarak anjakan ditentukan oleh panjang bahagian condong dan sudut.",
"Lasche {0}":"Bebibir {0}",
