"Mehrfachaufspannung: Nullpunktverschiebung gibt es in diesem Postprozessor nicht – „Eigener Nullpunkt je Teil“ wählen; nur ein Teil ausgegeben":"Berbilang bahagian: pasca-pemproses ini tiada anjakan titik sifar – pilih “Titik sifar sendiri bagi setiap bahagian”; hanya satu bahagian dioutput",
