"Meldet Bahnen, die tiefer schneiden als das Modell an dieser Stelle (Schaft-, Plan-, Kugel- und Torusfräser, Fasenfräser und Bohrer mit ihrem Kegel; 3-Achs-Bewegungen). Ein Schnitt, der nicht im Modell steht – Gravur, Eckenfreistich, Tasche nur aus einer Skizze – wird ebenfalls gemeldet.":"Melaporkan laluan yang memotong lebih dalam daripada model pada tempat itu (pemotong hujung, pemotong muka, pemotong bebola dan torus, pengisar chamfer dan gerudi dengan kon masing-masing; gerakan 3 paksi). Potongan yang tiada dalam model – ukiran, pelegaan sudut, poket daripada lakaran sahaja – turut dilaporkan.",
