"Nur lesen: der Agent sieht Entwurf, Modell, Bilder und NC-Programme, kann aber nichts ändern":"Baca sahaja: ejen melihat reka bentuk, model, gambar dan program NC, tetapi tidak boleh mengubah apa-apa",
