"Schraubstock: die Backen greifen quer zur X-Achse des Setups (an Y-min und Y-max des Rohteils); 0 = Größe und Spanntiefe passend wählen. Die Spannmittel werden einfache Körper am Ende der Zeitleiste und hier als Spannmittel eingetragen: Halter- und Kollisionsprüfung, Sicherheitsabstände und Einrichteblatt berücksichtigen sie.":"Ragum: rahang mencengkam melintang paksi X setup (pada Y-min dan Y-max bahan mentah); 0 = pilih saiz dan kedalaman cengkaman secara automatik. Alat pemegang menjadi jasad ringkas di hujung garis masa dan ditambah di sini sebagai alat pemegang: semakan pemegang dan perlanggaran, jarak selamat dan helaian setup mengambil kiranya.",
