"Schruppt die Bohrung von der Vorbohrung nach außen (0,2 mm Schlichtaufmaß) und schlichtet sie dann bis zum Grund. Die Bohrstange muss in die Vorbohrung passen.":"Memesin kasar lubang dari lubang pra-gerudi ke arah luar (elaun penamat 0,2 mm), kemudian menamatkannya hingga ke dasar. Bar korek mesti muat dalam lubang pra-gerudi.",
