"Tasche auf dem Umfang aus den geschlossenen Konturen einer Skizze, die längs zur Drehachse liegt (innere Konturen bleiben als Inseln stehen). Die Skizze wird auf den Durchmesser gewickelt; ein angetriebener Schaftfräser, der zur Achse zeigt, räumt von innen nach außen (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Der Fräser taucht auf einer Rampe entlang des innersten Rings ein.":"Poket pada lilitan daripada kontur tertutup sebuah lakaran yang terletak memanjang dengan paksi putaran (kontur dalam kekal sebagai pulau). Lakaran dililit pada diameter; pemotong hujung berpacu yang menghala ke paksi membuang bahan dari dalam ke luar (Z dan C bergerak bersama; Fanuc: interpolasi silinder G7.1). Pemotong masuk melalui ramp sepanjang cincin paling dalam.",
"Tasche bis zum Boden ausräumen":"Kosongkan poket hingga ke dasar",
"Tasche gespiegelt":"Poket bercermin",
"Tasche in den Mantel fräsen, die C-Achse dreht mit":"Kisar poket pada permukaan silinder, paksi C berputar bersama",
"Tasche in der Planfläche aus den geschlossenen Konturen einer Skizze (innere Konturen bleiben als Inseln stehen), mit einem angetriebenen Schaftfräser entlang Z. Geräumt wird von innen nach außen; der Fräser taucht auf einer Rampe entlang der innersten Bahn ein und bleibt innerhalb einer Ebene unten. X und C fahren gemeinsam (Fanuc: Polar-Interpolation G12.1). Tiefe ab Planfläche.":"Poket pada muka hujung daripada kontur tertutup sesuatu lakaran (kontur dalam kekal sebagai pulau), dengan pengisar hujung rata hidup sepanjang Z. Pembersihan dari dalam ke luar; pengisar masuk pada tanjakan di sepanjang laluan paling dalam dan kekal di bawah dalam satu aras. X dan C bergerak bersama (Fanuc: interpolasi kutub G12.1). Kedalaman dari muka hujung.",
