"Teil 1 liegt normalerweise auf dem Nullpunkt (0, 0, 0). Die anderen werden mit einer Nullpunktverschiebung angefahren (Heidenhain Zyklus 7, Fanuc/LinuxCNC G52, Sinumerik TRANS). Vor jedem Wechsel geht das Werkzeug auf die sichere Höhe.":"Bahagian 1 biasanya berada pada titik sifar (0, 0, 0). Yang lain dicapai dengan anjakan titik sifar (kitaran Heidenhain 7, Fanuc/LinuxCNC G52, Sinumerik TRANS). Sebelum setiap pertukaran alat bergerak ke ketinggian selamat.",
