"Teilt Kanten, die länger sind, in der Mitte (je Durchgang einmal) – die Form bleibt gleich. 0 teilt jede Kante: jedes Dreieck wird zu vier. Sinnvoll vor dem Glätten grober Netze.":"Membahagi tepi yang lebih panjang di tengah (sekali setiap lintasan) – bentuk kekal sama. 0 membahagi setiap tepi: setiap segi tiga menjadi empat. Berguna sebelum melicinkan jejaring kasar.",
