"Verrechnet zwei geschlossene Netze wirklich miteinander: innen liegende Flächen verschwinden, die Schnittkanten werden neu vernetzt. Gerechnet wird nur dort, wo sich die beiden Netze begegnen können – ein großes Netz mit einem kleinen Eingriff geht deshalb schnell. Überlappen zwei große Netze ganz, vorher „Reduzieren“.":"Benar-benar mengira dua jejaring tertutup antara satu sama lain: muka di bahagian dalam hilang, tepi keratan dijejaringkan semula. Pengiraan hanya dibuat di tempat kedua-dua jejaring boleh bertemu – jadi jejaring besar dengan campur tangan kecil berjalan pantas. Jika dua jejaring besar bertindih sepenuhnya, „Kurangkan“ dahulu.",
