"Verschraubung: Scheiben und Mutter kommen mit der Schraube in einem Zug an jede angeklickte Bohrung. Die Klemmdicke ist die Länge der Bohrung – durch mehrere Teile hindurch, wenn ihre Bohrungen fluchten und aneinanderstoßen. Mit Mutter wird die kürzeste Vorzugslänge vorgeschlagen, bei der die Schraube zwei Gewindegänge aus der Mutter ragt.":"Sambungan skru: pencuci dan nat diletakkan bersama skru dalam satu langkah pada setiap lubang yang diklik. Ketebalan apitan ialah panjang lubang – melalui beberapa bahagian jika lubangnya selari dan bersentuhan. Dengan nat, panjang pilihan terpendek dicadangkan di mana skru menonjol dua lilitan ulir daripada nat.",
