"Wickelt die Skizzenkurven auf den Zylinder: X bleibt X, der Abstand quer zur Achse wird zum Bogen auf dem Abwicklungs-Ø (Drehung A). Die Skizze muss parallel zur A-Achse liegen, z. B. auf einer Tangentialebene. Gefräst wird in fester Tiefe unter der Teiloberfläche – für Gravuren, Schriften und Nuten rund um das Teil.":"Melilit lengkung lakaran pada silinder: X kekal X, jarak melintang paksi menjadi lengkok pada Ø lilitan (putaran A). Lakaran mesti selari dengan paksi A, cth. pada satah tangen. Pengisaran pada kedalaman tetap di bawah permukaan bahagian – untuk ukiran, tulisan dan alur mengelilingi bahagian.",
"Wie 3D-Kontur, aber das Werkzeug fährt ohne Absätze kontinuierlich nach unten – keine Eintauchmarken an steilen Wänden.":"Seperti kontur 3D, tetapi alat bergerak ke bawah secara berterusan tanpa anak tangga – tiada kesan tusukan pada dinding curam.",
"Wie Einfahrt":"Sama seperti kemasukan",
"Wie ausgewählt":"Seperti dipilih",
"Wie die Ansicht":"Seperti paparan",
"Wie die Ansicht (alle Dreiecke)":"Seperti paparan (semua segi tiga)",
"Wie fein Körper für STL, 3MF und den Slicer in Dreiecke zerlegt werden: Abweichung von der wahren Fläche als Anteil der Körpergröße. Netze bleiben, wie sie sind.":"Betapa halus jasad dipecahkan kepada segi tiga untuk STL, 3MF dan Slicer: sisihan daripada permukaan sebenar sebagai nisbah saiz jasad. Mesh kekal seperti asal.",
"Wie fein Zylinder, Kugeln und Rundungen in der Ansicht aus Dreiecken bestehen. Feiner sieht runder aus, rechnet bei großen Modellen aber länger. Der Export hat eine eigene Einstellung (3D-Druck).":"Betapa halus silinder, sfera dan pembulatan dalam paparan terdiri daripada segi tiga. Lebih halus kelihatan lebih bulat, tetapi pengiraan model besar mengambil masa lebih lama. Eksport mempunyai tetapan sendiri (cetakan 3D).",
"Wie im System":"Seperti dalam sistem",
"Wie lange die Schneide schneiden darf, bevor sie getauscht wird. Das Fenster „Bearbeitungszeit“ rechnet daraus, wie viele Teile noch möglich sind.":"Berapa lama mata pemotong boleh memotong sebelum diganti. Tetingkap “Masa pemesinan” mengira daripadanya berapa banyak bahagian lagi yang boleh dibuat.",
