"Zungen stehen am freien Ende der Lasche über und kommen in den Zuschnitt. „Schlitze als Skizze“ legt die passenden Schlitze dort an, wo die Zungen stehen – je Ebene eine Skizze, jeder Schlitz ringsum um das Spiel größer als die Zunge. In dieser Skizze den Umriss des Gegenstücks zeichnen und daraus ein Blech oder eine Extrusion machen: die Schlitze werden Ausschnitte. Das Gegenstück liegt auf den Laschenenden auf; die Zungenlänge ist üblich gleich seiner Dicke.":"Lidah menonjol pada hujung bebas bebibir dan menjadi sebahagian daripada potongan. „Alur sebagai lakaran“ mencipta alur yang sepadan di tempat lidah berada – satu lakaran bagi setiap satah, setiap alur lebih besar daripada lidah di sekelilingnya sebanyak kelegaan. Lukis garis bentuk bahagian pasangan dalam lakaran ini dan jadikannya kepingan atau ekstrusi: alur menjadi potongan keluar. Bahagian pasangan terletak pada hujung bebibir; panjang lidah lazimnya sama dengan ketebalannya.",
