"{0}: Postprozessor ohne Vorlage „C-Achse und angetriebenes Werkzeug ein“ – C-Achse und Werkzeugspindel von Hand einschalten":"{0}: Pasca-pemproses tanpa templat “Paksi C dan alat bergerak hidup” – hidupkan paksi C dan gelendong alat secara manual",
