"„+“ = Werkzeug wird neu angelegt. Schnittdaten sind Richtwerte für Hartmetall ({0}){1}; Kühlung: {2}.":"“+” = alat akan dicipta baharu. Data pemotongan ialah nilai panduan untuk karbida ({0}){1}; penyejukan: {2}.",
"„Ineinander schachteln“ legt die Zuschnitte in die Lücken und Buchten ihrer Nachbarn und in deren Ausschnitte (ohne 90°-Drehen nur um 180° gewendet); der Abstand wird nie unterschritten. Ohne den Haken liegen sie nach ihrem umschließenden Rechteck in Reihen. Mit „Skizze + Körper“ entstehen flache Körper in Blechdicke, die sich in der Fertigung mit 2D-Kontur ausschneiden lassen.":"„Susun saling menyelit“ meletakkan blank potongan ke dalam ruang kosong dan lekukan jirannya serta ke dalam potongan keluarnya (tanpa putaran 90° hanya dipusing 180°); jarak tidak pernah dikurangkan. Tanpa tanda semak, ia diletakkan dalam baris mengikut segi empat tepat yang mengelilinginya. Dengan „Lakaran + jasad“ terhasil jasad rata setebal kepingan yang boleh dipotong dalam pembuatan dengan kontur 2D.",
"„Innen/Außen“ braucht geschlossene Konturen – offene Kurven mit „Auf der Kurve“ fräsen":"“Dalam/Luar” memerlukan kontur tertutup – kisar lengkung terbuka dengan “Pada lengkung”",
"„Prüfen“ fährt den Ablauf in kleinen Zeitschritten ab und meldet, wann welche Körper zusammenstoßen.":"“Semak” menjalankan urutan dalam langkah masa kecil dan melaporkan bila jasad mana yang berlanggar.",
"„Skizze fertig“ → Extrusion, Rotation oder Bohrung.":"„Lakaran siap“ → Ekstrusi, Putaran atau Lubang.",
"„Skizze“ → Ebene XY/XZ/YZ wählen oder eine ebene Fläche anklicken.":"„Lakaran“ → pilih satah XY/XZ/YZ atau klik muka rata.",
"„{0}“ als Netz übernommen – {1} Dreiecke. Der Körper ist ausgeblendet.":"„{0}“ diambil sebagai jejaring – {1} segi tiga. Jasad disembunyikan.",
